116	
117	    onInit() {
118	      this.updateTime()
119	      this.timeTimer = setInterval(() => { this.updateTime() }, 30000)
120	    },
121	
122	    // onShow 时 DOM 已 ready，获取屏幕信息做顶部安全偏移适配（仅执行一次）
123	    onShow() {
124	      if (this.screenAdjusted) return
125	      this.screenAdjusted = true
126	      this.adjustForScreen()
127	    },
128	
129	    onDestroy() {
130	      if (this.timeTimer) clearInterval(this.timeTimer)
131	    },
132	
133	    updateTime() {
134	      var now = new Date()
135	      var h = now.getHours().toString().padStart(2, '0')
136	      var m = now.getMinutes().toString().padStart(2, '0')
137	      this.time = h + ':' + m
138	    },
139	
140	    // 屏幕形态/分辨率动态安全偏移：避免顶部时间被系统状态栏遮挡。
141	    // 物理安全偏移按实测微调（物理像素）；换算为设计 px：设计px = N × 300 ÷ screenWidth
142	    adjustForScreen() {
143	      var self = this
144	      device.getInfo({
145	        success: function(data) {
146	          var screenWidth = data.screenWidth
147	          var shape = data.screenShape
148	          if (!screenWidth) return
149	          var safeTopPx = 0 // 物理安全偏移（物理像素，按实测微调）
150	          var base = 28
151	          if (shape === 'pill-shaped') {
152	            safeTopPx = 12
153	            base = 30
154	          } else if (shape === 'circle') {
155	            safeTopPx = 10
156	            base = 20
157	          }
158	          var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
159	          self.topBarPadTop = padTop
160	          self.statusbarHeight = base + padTop
161	        }
162	      })
